nextflow_process {

    name "Test Process OPT_STAT"
    script "../main.nf"
    process "OPT_STAT"

    tag "modules"
    tag "modules_nfcore"
    tag "opt"
    tag "opt/flip"
    tag "opt/track"
    tag "opt/stat"

    setup {
        run("OPT_FLIP") {
            script "../../flip/main.nf"
            process {
                """
                input[0] = [
                    [ id:'testrun_opt_stat' ],
                    file(params.modules_testdata_base_path + 'spatial_omics/probe_detection/probes.fa', checkIfExists: true)
                ]
                input[1] = [
                    [ id:'test_references' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/minigenome.gtf', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/minigenome.fa', checkIfExists: true)
                ]
                """
            }
        }

        run("OPT_TRACK") {
            script "../../track/main.nf"
            process {
                """
                input[0] = OPT_FLIP.out.fwd_oriented_fa
                input[1] = [
                    [ id:'test_references' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/minigenome.gtf', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/minigenome.fa', checkIfExists: true)
                ]
                """
            }
        }
    }

    test("testrun opt/stat panel probe sequences") {

        when {

            process {
                """
                input[0] = OPT_TRACK.out.probes2target
                input[1] = OPT_FLIP.out.fwd_oriented_fa
                input[2] = [file(params.modules_testdata_base_path + 'spatial_omics/probe_detection/gene_synonyms.csv', checkIfExists: true)]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("testrun opt/stat panel probe sequences -stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = OPT_TRACK.out.probes2target
                input[1] = OPT_FLIP.out.fwd_oriented_fa
                input[2] = [file(params.modules_testdata_base_path + 'spatial_omics/probe_detection/gene_synonyms.csv', checkIfExists: true)]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }
}

